import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------
# CUDA kernel implementation (half precision inputs, fp32 accumulation)
# ------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void hinge_loss_kernel(const scalar_t* __restrict__ pred,
                                  const scalar_t* __restrict__ targ,
                                  float* __restrict__ block_sum,
                                  const int N) {
    // each thread processes multiple elements
    float sum = 0.0f;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    for (int i = idx; i < N; i += stride) {
        float p = __half2float(pred[i]);
        float t = __half2float(targ[i]);
        float loss = 1.0f - p * t;
        if (loss > 0.0f) sum += loss;
    }

    // ---- intra‑warp reduction (shuffle) ----
    for (int offset = warpSize/2; offset > 0; offset /= 2) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
    }

    // ---- warp leaders write to shared memory ----
    __shared__ float shmem[32];               // max 32 warps per block
    if (threadIdx.x % warpSize == 0) {
        shmem[threadIdx.x / warpSize] = sum;
    }
    __syncthreads();

    // ---- final reduction by first warp ----
    if (threadIdx.x < 32) {
        sum = (threadIdx.x < (blockDim.x / warpSize)) ? shmem[threadIdx.x] : 0.0f;
        for (int offset = warpSize/2; offset > 0; offset /= 2) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
        }
        if (threadIdx.x == 0) {
            block_sum[blockIdx.x] = sum;
        }
    }
}

torch::Tensor hinge_loss_cuda(torch::Tensor pred, torch::Tensor targ) {
    const int N = pred.numel();
    const int threads = 256;
    const int blocks = (N + threads - 1) / threads;

    auto options = torch::TensorOptions()
                       .dtype(torch::kFloat32)
                       .device(pred.device());
    auto partial = torch::zeros({blocks}, options);

    AT_DISPATCH_HALF_TYPES(pred.scalar_type(), "hinge_loss_kernel", ([&] {
        hinge_loss_kernel<scalar_t><<<blocks, threads>>>(
            pred.data_ptr<scalar_t>(),
            targ.data_ptr<scalar_t>(),
            partial.data_ptr<float>(),
            N);
    }));
    cudaDeviceSynchronize();

    // sum the partial results on the device, then compute mean
    float total = partial.sum().item<float>();
    float mean = total / static_cast<float>(N);

    // return as a scalar half tensor
    auto out = torch::empty({1},
        torch::TensorOptions().dtype(torch::kFloat16).device(pred.device()));
    out[0] = __float2half(mean);
    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("hinge_loss", &hinge_loss_cuda, "Hinge loss (CUDA)");
}
'''

# Compile the inline extension
hinge_ext = load_inline(name='hinge_ext',
                        cpp_sources='',
                        cuda_sources=cuda_source,
                        functions=['hinge_loss'],
                        verbose=False)

# ------------------------------------------------------------
# PyTorch model that uses the custom kernel
# ------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, predictions, targets):
        # ensure inputs are half and on CUDA
        preds = predictions.to(dtype=torch.float16, device='cuda')
        targs = targets.to(dtype=torch.float16, device='cuda')
        # kernel returns a 1‑element half tensor; squeeze to match torch.mean output shape
        return hinge_ext.hinge_loss(preds, targs).squeeze()

# ------------------------------------------------------------
# Helper functions matching the reference API
# ------------------------------------------------------------
def get_inputs():
    batch_size = 32768
    preds = torch.rand(batch_size, dtype=torch.float16, device='cuda')
    # targets ∈ {‑1, +1}
    targs = (torch.randint(0, 2, (batch_size,), device='cuda', dtype=torch.float16) * 2 - 1)
    return [preds, targs]

def get_init_inputs():
